from threetears.evals import Eval

from sentiment import score

def rate_review(case):
    """The dashboard's score for the review."""
    return {"score": score(case["text"])}


def agrees_with_panel(case, out):
    """The score is within 0.25 of the panel's mean rating, as the README counts agreement."""
    return abs(out["score"] - case["panel"]) <= 0.25 + 1e-9

reviews = Eval("data/rated_reviews.jsonl", runner=rate_review, grader=[agrees_with_panel], k=1)
